#pragma once

#include <cstddef>
#include <cstdint>

namespace embed::display {

/// One image embedded from assets/ at build time.
/// The table of all embedded images is generated by CMake
/// (see components/display/CMakeLists.txt).
struct ImageAsset {
    const char* name;    ///< file name with extension, e.g. "barmen-idle.png" or "barmen-idle.gif"
    const uint8_t* data; ///< raw file bytes in flash (.rodata): original PNG or GIF bytes
    size_t size;         ///< file size in bytes
};

/// Look up an embedded image by file name without extension.
/// Returns nullptr when no image with that name was embedded.
const ImageAsset* findImage(const char* name);

} // namespace embed::display
